def fill_between_markers(grid):
    """Background cells with a marker on both sides in their row or column become the fill color (marker color+? )..."""
    h,w=len(grid),len(grid[0])
    from collections import Counter
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    nonbg=[v for v in cnt if v!=bg]
    mk=nonbg[0]; fill=3
    out=[r[:] for r in grid]
    for i in range(h):
        rs=[c for c in range(w) if grid[i][c]==mk]
        for j in range(w):
            if grid[i][j]==bg and any(c<j for c in rs) and any(c>j for c in rs):
                out[i][j]=fill
    for j in range(w):
        cs=[r for r in range(h) if grid[r][j]==mk]
        for i in range(h):
            if grid[i][j]==bg and any(r<i for r in cs) and any(r>i for r in cs):
                out[i][j]=fill
    return out
