    h,w=len(grid),len(grid[0])
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    nonbg=[v for v in cnt if v!=bg]
    if not nonbg: return [r[:] for r in grid]
    mk=nonbg[0]
    out=[r[:] for r in grid]
    for i in range(h):
        rs=[c for c in range(w) if grid[i][c]==mk]
        for j in range(w):
            if grid[i][j]==bg and any(c<j for c in rs) and any(c>j for c in rs):
                out[i][j]=3
    for j in range(w):
        cs=[r for r in range(h) if grid[r][j]==mk]
        for i in range(h):
            if grid[i][j]==bg and any(r<i for r in cs) and any(r>i for r in cs):
                out[i][j]=3
    return out
